{
  "root": "main_stack",
  "state": {
    "ingredients": [
      {
        "item": "Unsalted butter, softened",
        "quantity": "1/2 cup (113g)"
      },
      {
        "item": "Granulated sugar",
        "quantity": "1/2 cup (100g)"
      },
      {
        "item": "Packed light brown sugar",
        "quantity": "1/4 cup (50g)"
      },
      {
        "item": "Large egg",
        "quantity": "1"
      },
      {
        "item": "Vanilla extract",
        "quantity": "1 teaspoon"
      },
      {
        "item": "All-purpose flour",
        "quantity": "1 1/4 cups (150g)"
      },
      {
        "item": "Baking soda",
        "quantity": "1/2 teaspoon"
      },
      {
        "item": "Salt",
        "quantity": "1/4 teaspoon"
      },
      {
        "item": "Semi-sweet chocolate chips",
        "quantity": "1 cup (170g)"
      }
    ],
    "equipment": [
      {
        "item": "Large mixing bowl"
      },
      {
        "item": "Hand mixer or stand mixer"
      },
      {
        "item": "Rubber spatula or wooden spoon"
      },
      {
        "item": "Measuring cups and spoons"
      },
      {
        "item": "Baking sheets"
      },
      {
        "item": "Parchment paper or silicone baking mats"
      },
      {
        "item": "Wire cooling rack"
      }
    ],
    "pro_tips": [
      {
        "tip": "Room Temperature Ingredients",
        "description": "Ensure butter and egg are at room temperature for a smoother, more uniform dough."
      },
      {
        "tip": "Don't Overmix",
        "description": "Overmixing develops gluten, which can make cookies tough. Mix until just combined."
      },
      {
        "tip": "Chill Time",
        "description": "Chilling the dough solidifies the fat, preventing cookies from spreading too much and intensifying flavor."
      },
      {
        "tip": "Even Baking",
        "description": "Rotate your baking sheets halfway through baking for uniform browning."
      },
      {
        "tip": "Storage",
        "description": "Store cooled cookies in an airtight container at room temperature for up to 3-4 days."
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_stack",
        "intro_text",
        "ingredients_heading",
        "ingredients_table",
        "equipment_heading",
        "equipment_table",
        "baking_guide_heading",
        "baking_guide_tabs",
        "pro_tips_heading",
        "pro_tips_table",
        "quick_actions_heading",
        "quick_actions_stack"
      ]
    },
    "title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "recipe_icon",
        "recipe_title"
      ]
    },
    "recipe_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000146_01_2_cup-hot.svg"
      },
      "children": []
    },
    "recipe_title": {
      "type": "Text",
      "props": {
        "text": "Classic Chocolate Chip Cookie Recipe",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "This guide provides a classic chocolate chip cookie recipe, assuming standard kitchen equipment and common pantry staples. It yields soft, chewy cookies with crispy edges."
      },
      "children": []
    },
    "ingredients_heading": {
      "type": "Text",
      "props": {
        "text": "Ingredients for Delicious Cookies",
        "variant": "h2"
      },
      "children": []
    },
    "ingredients_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "item",
            "label": "Ingredient"
          },
          {
            "key": "quantity",
            "label": "Quantity"
          }
        ],
        "statePath": "/ingredients",
        "domain": "generic",
        "preferredPresentation": "table"
      },
      "children": []
    },
    "equipment_heading": {
      "type": "Text",
      "props": {
        "text": "Essential Baking Equipment",
        "variant": "h2"
      },
      "children": []
    },
    "equipment_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "item",
            "label": "Equipment"
          }
        ],
        "statePath": "/equipment",
        "domain": "generic",
        "preferredPresentation": "table"
      },
      "children": []
    },
    "baking_guide_heading": {
      "type": "Text",
      "props": {
        "text": "Your Step-by-Step Baking Guide",
        "variant": "h2"
      },
      "children": []
    },
    "baking_guide_tabs": {
      "type": "Tabs",
      "props": {
        "tabs": [
          {
            "title": "Step 1",
            "child": "step1_card"
          },
          {
            "title": "Step 2",
            "child": "step2_card"
          },
          {
            "title": "Step 3",
            "child": "step3_card"
          },
          {
            "title": "Step 4",
            "child": "step4_card"
          },
          {
            "title": "Step 5",
            "child": "step5_card"
          },
          {
            "title": "Step 6",
            "child": "step6_card"
          },
          {
            "title": "Step 7",
            "child": "step7_card"
          },
          {
            "title": "Step 8",
            "child": "step8_card"
          },
          {
            "title": "Step 9",
            "child": "step9_card"
          }
        ]
      },
      "children": []
    },
    "step1_card": {
      "type": "Card",
      "props": {},
      "children": [
        "step1_stack"
      ]
    },
    "step1_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "start"
      },
      "children": [
        "step1_icon",
        "step1_text"
      ]
    },
    "step1_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000164_01_2_hand-index.svg"
      },
      "children": []
    },
    "step1_text": {
      "type": "Text",
      "props": {
        "text": "In a large bowl, cream together the softened butter, granulated sugar, and brown sugar until the mixture is light and fluffy. This usually takes about 2-3 minutes with an electric mixer."
      },
      "children": []
    },
    "step2_card": {
      "type": "Card",
      "props": {},
      "children": [
        "step2_stack"
      ]
    },
    "step2_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "start"
      },
      "children": [
        "step2_icon",
        "step2_text"
      ]
    },
    "step2_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000164_01_3_egg.svg"
      },
      "children": []
    },
    "step2_text": {
      "type": "Text",
      "props": {
        "text": "Beat in the large egg until just combined, then stir in the vanilla extract. Scrape down the sides of the bowl to ensure everything is well incorporated."
      },
      "children": []
    },
    "step3_card": {
      "type": "Card",
      "props": {},
      "children": [
        "step3_stack"
      ]
    },
    "step3_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "start"
      },
      "children": [
        "step3_icon",
        "step3_text"
      ]
    },
    "step3_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000164_01_4_cloud-drizzle.svg"
      },
      "children": []
    },
    "step3_text": {
      "type": "Text",
      "props": {
        "text": "In a separate medium bowl, whisk together the all-purpose flour, baking soda, and salt. This ensures the leavening agent is evenly distributed."
      },
      "children": []
    },
    "step4_card": {
      "type": "Card",
      "props": {},
      "children": [
        "step4_text"
      ]
    },
    "step4_text": {
      "type": "Text",
      "props": {
        "text": "Gradually add the dry ingredients to the wet ingredients, mixing on low speed until just combined. Be careful not to overmix, as this can lead to tough cookies."
      },
      "children": []
    },
    "step5_card": {
      "type": "Card",
      "props": {},
      "children": [
        "step5_stack"
      ]
    },
    "step5_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "start"
      },
      "children": [
        "step5_icon",
        "step5_text"
      ]
    },
    "step5_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000152_01_4_droplet.svg"
      },
      "children": []
    },
    "step5_text": {
      "type": "Text",
      "props": {
        "text": "Gently fold in the chocolate chips using a rubber spatula until they are evenly distributed throughout the dough."
      },
      "children": []
    },
    "step6_card": {
      "type": "Card",
      "props": {},
      "children": [
        "step6_stack"
      ]
    },
    "step6_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "start"
      },
      "children": [
        "step6_icon",
        "step6_text"
      ]
    },
    "step6_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000164_01_7_snow.svg"
      },
      "children": []
    },
    "step6_text": {
      "type": "Text",
      "props": {
        "text": "For best results and chewier cookies, cover the bowl with plastic wrap and chill the dough in the refrigerator for at least 30 minutes, or up to 24 hours. This helps prevent spreading."
      },
      "children": []
    },
    "step7_card": {
      "type": "Card",
      "props": {},
      "children": [
        "step7_text"
      ]
    },
    "step7_text": {
      "type": "Text",
      "props": {
        "text": "Preheat your oven to 375°F (190°C). Line baking sheets with parchment paper or silicone baking mats."
      },
      "children": []
    },
    "step8_card": {
      "type": "Card",
      "props": {},
      "children": [
        "step8_stack"
      ]
    },
    "step8_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "start"
      },
      "children": [
        "step8_icon",
        "step8_text"
      ]
    },
    "step8_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000164_01_9_cookie.svg"
      },
      "children": []
    },
    "step8_text": {
      "type": "Text",
      "props": {
        "text": "Drop rounded tablespoons of cookie dough onto the prepared baking sheets, leaving about 2 inches between each cookie. Bake for 9-11 minutes, or until the edges are golden brown and the centers are still slightly soft."
      },
      "children": []
    },
    "step9_card": {
      "type": "Card",
      "props": {},
      "children": [
        "step9_stack"
      ]
    },
    "step9_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "start"
      },
      "children": [
        "step9_icon",
        "step9_text"
      ]
    },
    "step9_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000164_01_10_grid.svg"
      },
      "children": []
    },
    "step9_text": {
      "type": "Text",
      "props": {
        "text": "Let the cookies cool on the baking sheets for 2-3 minutes before transferring them to a wire rack to cool completely. Enjoy your freshly baked chocolate chip cookies!"
      },
      "children": []
    },
    "pro_tips_heading": {
      "type": "Text",
      "props": {
        "text": "Pro Tips for Success",
        "variant": "h2"
      },
      "children": []
    },
    "pro_tips_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "tip",
            "label": "Tip"
          },
          {
            "key": "description",
            "label": "Description"
          }
        ],
        "statePath": "/pro_tips",
        "domain": "generic",
        "preferredPresentation": "cards",
        "primaryColumn": "tip"
      },
      "children": []
    },
    "quick_actions_heading": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "find_more_button",
        "learn_baking_button"
      ]
    },
    "find_more_button": {
      "type": "Button",
      "props": {
        "label": "Find More Cookie Recipes: Allrecipes"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.allrecipes.com/recipes/102/desserts/cookies/"
          }
        }
      },
      "children": []
    },
    "learn_baking_button": {
      "type": "Button",
      "props": {
        "label": "Learn About Baking Basics: Food Network"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.foodnetwork.com/how-to/packages/food-network-essentials/baking-guide"
          }
        }
      },
      "children": []
    }
  }
}
